function FinanceOnlyView({ expenses, invoices, returns, commissions, pendingTotal, outstandingTotal, settings, dialog, setDialog, selectedExpense, setSelectedExpense, selectedInvoice, setSelectedInvoice, updateExpense, processRefund, saved }: { expenses: Expense[]; invoices: Invoice[]; returns: ReturnRecord[]; commissions: Commission[]; pendingTotal: number; outstandingTotal: number; settings: ReturnType<typeof useOrganizationSettings>; dialog: FinanceDialog; setDialog: Dispatch<SetStateAction<FinanceDialog>>; selectedExpense: Expense | null; setSelectedExpense: Dispatch<SetStateAction<Expense | null>>; selectedInvoice: Invoice | null; setSelectedInvoice: Dispatch<SetStateAction<Invoice | null>>; updateExpense: (expense: Expense, status: 'Approved' | 'Rejected' | 'Paid') => Promise<void>; processRefund: (record: ReturnRecord) => Promise<void>; saved: (message: string) => void }) {
  const overdue = invoices.filter(invoice => Number(invoice.outstanding) > 0 && invoice.due_at && new Date(invoice.due_at).getTime() < Date.now());
  return <><div className="ops-kpis"><LiveKpi label="Pending expenses" value={formatCurrency(pendingTotal, settings.currency)} note="Awaiting finance review" icon={<FileText size={16}/>} tone="amber"/><LiveKpi label="Outstanding debtors" value={formatCurrency(outstandingTotal, settings.currency)} note="Open invoice balances" icon={<CircleDollarSign size={16}/>} tone="blue"/><LiveKpi label="Overdue debtors" value={overdue.length} note={formatCurrency(overdue.reduce((sum, invoice) => sum + Number(invoice.outstanding || 0), 0), settings.currency)} icon={<CircleDollarSign size={16}/>} tone="red"/><LiveKpi label="Commission entries" value={commissions.length.toString()} note="Settlement ledger" icon={<Users size={16}/>} tone="purple"/></div><div className="workflow-actions"><button className="ops-btn blue" onClick={() => setDialog('expense')}><Plus size={15}/> Submit expense</button></div><div className="ops-grid-two"><LivePanel title="Payments and debtors" subtitle="Invoices, balances, and payment records"><div className="data-table"><TableHead labels={['Invoice','Client','Outstanding','Status','Action']}/>{invoices.map(invoice => <div className="data-row" key={invoice.id}><div><strong>{invoice.number}</strong><small>{invoice.sale_number}</small></div><span>{invoice.client_name}</span><span>{formatCurrency(invoice.outstanding, settings.currency)}</span><Status value={Number(invoice.outstanding) <= 0 ? 'Paid' : invoice.status}/><div className="transfer-card-actions"><button className="row-action" onClick={() => { setSelectedInvoice(invoice); setDialog('invoiceDetail'); }}>Details</button><button className="row-action" disabled={invoice.status === 'Void' || Number(invoice.outstanding) <= 0} onClick={() => { setSelectedInvoice(invoice); setDialog('payment'); }}>Record payment</button></div></div>)}{!invoices.length && <Empty title="No invoices" detail="Confirmed-sale invoices will appear here." icon={<FileText size={22}/>}/>}</div></LivePanel><LivePanel title="Expense approvals" subtitle="Receipt-backed expense claims"><div className="data-table"><TableHead labels={['Expense','Description','Amount','Status','Action']}/>{expenses.map(expense => <div className="data-row" key={expense.id}><div><strong>{expense.number}</strong><small>{expense.category}</small></div><span>{expense.description}</span><span>{formatCurrency(expense.amount, settings.currency)}</span><Status value={expense.status}/><div className="transfer-card-actions"><button className="row-action" onClick={() => { setSelectedExpense(expense); setDialog('expenseDetail'); }}>Details</button>{expense.status === 'Pending' && <><button className="row-action" onClick={() => void updateExpense(expense, 'Approved')}><Check size={13}/> Approve</button><button className="row-action" onClick={() => void updateExpense(expense, 'Rejected')}><X size={13}/> Reject</button></>}</div></div>)}{!expenses.length && <Empty title="No expenses" detail="No expense claims are waiting." icon={<CircleDollarSign size={22}/>}/>}</div></LivePanel></div><LivePanel title="Returns and refunds" subtitle="Finance-controlled refund and credit-note processing"><div className="data-table"><TableHead labels={['Return','Client','Amount','Status','Action']}/>{returns.map(record => <div className="data-row" key={record.id}><strong>{record.number}</strong><span>{record.client_name}</span><span>{formatCurrency(record.refund_amount, settings.currency)}</span><Status value={record.refund_status}/>{record.refund_status === 'Pending' ? <button className="row-action" onClick={() => void processRefund(record)}>Process refund</button> : <span className="workflow-help">Recorded</span>}</div>)}{!returns.length && <Empty title="No returns" detail="Completed sales returns will appear here." icon={<RotateCcw size={22}/>}/>}</div></LivePanel>{dialog === 'expense' && <ExpenseDialog close={() => setDialog(null)} saved={() => saved('Expense submitted')}/>} {dialog === 'expenseDetail' && selectedExpense && <ExpenseDetailDialog expense={selectedExpense} close={() => setDialog(null)}/>} {dialog === 'payment' && selectedInvoice && <PaymentDialog invoice={selectedInvoice} close={() => setDialog(null)} saved={() => saved('Payment recorded')}/>} {dialog === 'invoiceDetail' && selectedInvoice && <InvoiceDetailDialog invoice={selectedInvoice} close={() => setDialog(null)} openPayment={() => setDialog('payment')}/>}</>;
}

function ManagerControlView({ employees, tasks, rules, targets, users, dialog, setDialog, selectedEmployee, setSelectedEmployee, selectedRule, setSelectedRule, selectedTarget, setSelectedTarget, completeTask, offboard, saved, notify }: { employees: Employee[]; tasks: OnboardingTask[]; rules: Rule[]; targets: Target[]; users: User[]; dialog: FinanceDialog; setDialog: Dispatch<SetStateAction<FinanceDialog>>; selectedEmployee: Employee | null; setSelectedEmployee: Dispatch<SetStateAction<Employee | null>>; selectedRule: Rule | null; setSelectedRule: Dispatch<SetStateAction<Rule | null>>; selectedTarget: Target | null; setSelectedTarget: Dispatch<SetStateAction<Target | null>>; completeTask: (task: OnboardingTask) => Promise<void>; offboard: (employee: Employee) => Promise<void>; saved: (message: string) => void; notify: (message: string) => void }) {
  return <><div className="ops-kpis"><LiveKpi label="Active people" value={employees.filter(employee => employee.is_active).length.toString()} note="Consultants and staff" icon={<Users size={16}/>} tone="purple"/><LiveKpi label="Pending onboarding" value={tasks.filter(task => task.status === 'Pending').length.toString()} note="Tasks needing follow-up" icon={<Check size={16}/>} tone="amber"/><LiveKpi label="Commission rules" value={rules.length.toString()} note="Manager-configured" icon={<CircleDollarSign size={16}/>} tone="blue"/><LiveKpi label="Consultant targets" value={targets.length.toString()} note="Current target plans" icon={<FileText size={16}/>} tone="green"/></div><div className="workflow-actions"><button className="ops-btn blue" onClick={() => setDialog('employeeCreate')}><Plus size={15}/> Add consultant</button><button className="ops-btn ghost" onClick={() => setDialog('onboarding')}><Plus size={15}/> Add onboarding task</button><button className="ops-btn ghost" onClick={() => setDialog('rule')}><Plus size={15}/> Commission setting</button><button className="ops-btn ghost" onClick={() => setDialog('target')}><Plus size={15}/> Set target</button></div><div className="ops-grid-two"><LivePanel title="People and onboarding" subtitle="Manager-controlled consultant lifecycle"><div className="data-table"><TableHead labels={['Person','Role','Tasks','Action']}/>{employees.map(employee => <div className="data-row" key={employee.id}><div><strong>{employee.full_name}</strong><small>{employee.email} · {employee.last_event || 'No lifecycle event'}</small></div><span>{employee.role}</span><span>{employee.completed_tasks} done · {employee.pending_tasks} pending</span><div className="transfer-card-actions"><Status value={employee.is_active ? 'Active' : 'Inactive'}/><button className="row-action" onClick={() => { setSelectedEmployee(employee); setDialog('employeeHistory'); }}>History</button><button className="row-action" onClick={() => { setSelectedEmployee(employee); setDialog('employeeEdit'); }}>Edit</button>{employee.is_active && <button className="row-action" onClick={() => void offboard(employee)}>Offboard</button>}</div></div>)}{!employees.length && <Empty title="No people" detail="Add a sales consultant to begin." icon={<Users size={22}/>} />}</div><div className="data-table"><TableHead labels={['Onboarding task','Person','Due','Action']}/>{tasks.filter(task => task.status === 'Pending').map(task => <div className="data-row" key={task.id}><strong>{task.title}</strong><span>{task.user_name}</span><span>{task.due_at || 'No due date'}</span><button className="row-action" onClick={() => void completeTask(task)}><Check size={13}/> Complete</button></div>)}{!tasks.some(task => task.status === 'Pending') && <p className="workflow-help">No pending onboarding tasks.</p>}</div></LivePanel><LivePanel title="Commission settings and targets" subtitle="Manager-owned sales controls"><div className="data-table"><TableHead labels={['Rule','Rate','Trigger','Action']}/>{rules.map(rule => <div className="data-row" key={rule.id}><strong>{rule.name}</strong><span>{Number(rule.rate).toFixed(2)}%</span><span>{rule.trigger_status}</span><button className="row-action" onClick={() => { setSelectedRule(rule); setDialog('ruleEdit'); }}>Edit</button></div>)}{!rules.length && <p className="workflow-help">No commission rules configured.</p>}</div><div className="data-table"><TableHead labels={['Consultant','Period','Target','Action']}/>{targets.map(target => <div className="data-row" key={target.id}><strong>{target.consultant_name}</strong><span>{target.period_start} → {target.period_end}</span><span>{target.target_amount}</span><button className="row-action" onClick={() => { setSelectedTarget(target); setDialog('targetEdit'); }}>Edit</button></div>)}{!targets.length && <p className="workflow-help">No consultant targets configured.</p>}</div></LivePanel></div>{dialog === 'employeeCreate' && <EmployeeCreateDialog allowCeo={false} close={() => setDialog(null)} saved={() => saved('Consultant created')}/>} {dialog === 'employeeEdit' && selectedEmployee && <EmployeeEditDialog allowCeo={false} employee={selectedEmployee} close={() => { setDialog(null); setSelectedEmployee(null); }} saved={() => { setDialog(null); setSelectedEmployee(null); notify('Employee updated'); }}/>} {dialog === 'employeeHistory' && selectedEmployee && <EmployeeHistoryDialog employee={selectedEmployee} close={() => { setDialog(null); setSelectedEmployee(null); }}/>} {dialog === 'onboarding' && <OnboardingDialog users={users} close={() => setDialog(null)} saved={() => saved('Onboarding task created')}/>} {dialog === 'rule' && <RuleDialog close={() => setDialog(null)} saved={() => saved('Commission rule created')}/>} {dialog === 'ruleEdit' && selectedRule && <RuleEditDialog rule={selectedRule} close={() => setDialog(null)} saved={() => saved('Commission rule updated')}/>} {dialog === 'target' && <TargetDialog users={users} close={() => setDialog(null)} saved={() => saved('Consultant target created')}/>} {dialog === 'targetEdit' && selectedTarget && <TargetEditDialog target={selectedTarget} users={users} close={() => setDialog(null)} saved={() => { setDialog(null); setSelectedTarget(null); notify('Target updated'); }}/>}</>;
}

function Dialog({ title, children, close }: { title: string; children: React.ReactNode; close: () => void }) { const dialogRef = useDialogFocus<HTMLDivElement>(close); return <div className="workflow-dialog-backdrop" role="presentation" onMouseDown={event => { if (event.target === event.currentTarget) close(); }}><div ref={dialogRef} className="workflow-dialog" role="dialog" aria-modal="true" aria-label={title} tabIndex={-1}><div className="workflow-dialog-head"><h3>{title}</h3><button onClick={close} aria-label="Close"><X size={16}/></button></div>{children}</div></div>; }
function Field({ label, children }: { label: string; children: React.ReactNode }) { return <label className="workflow-field"><span>{label}</span>{children}</label>; }
function Actions({ close, label, disabled }: { close: () => void; label: string; disabled?: boolean }) { return <div className="workflow-dialog-actions"><button type="button" className="ops-btn ghost" onClick={close}>Cancel</button><button className="ops-btn blue" disabled={disabled}>{label}</button></div>; }
function LivePanel({ title, subtitle, children }: { title: string; subtitle: string; children: React.ReactNode }) { return <section className="ops-panel"><div className="ops-panel-head"><div><h2>{title}</h2><p>{subtitle}</p></div></div>{children}</section>; }
function TableHead({ labels }: { labels: string[] }) { return <div className="table-head ops-table-head">{labels.map(label => <span key={label}>{label}</span>)}</div>; }
function Status({ value }: { value: string }) { const key = value.toLowerCase().replaceAll(' ', '-'); return <span className={`status ${key}`}>{value}</span>; }
function LiveKpi({ label, value, note, icon, tone }: { label: string; value: string | number; note: string; icon: React.ReactNode; tone: string }) { return <div className="ops-kpi"><span className={`kpi-icon ${tone}`}>{icon}</span><strong>{value}</strong><span>{label}</span><small>{note}</small></div>; }
function Empty({ title, detail, icon }: { title: string; detail: string; icon: React.ReactNode }) { return <div className="empty-state">{icon}<strong>{title}</strong><span>{detail}</span></div>; }
